cd /tmp/ross-main && python3 - <<'PY'
import re,subprocess
# map sha->branch
sha_branch={}
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','-C','/tmp/ross-main','log','--format=%H',f'origin/friend/{b}']).decode().split()
    for s in out: sha_branch[s]=b
# all friend-message commits
allshas=set()
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    commits=subprocess.check_output(['git','-C','/tmp/ross-main','log','--format=%H',f'origin/friend/{b}']).decode().split()
    for sha in commits:
        body=subprocess.check_output(['git','-C','/tmp/ross-main','show','-s','--format=%B',sha]).decode()
        if 'Friend-Message: 1' in body:
            allshas.add(sha)
# shas in all transcript files
fileshas=set()
import glob
for f in glob.glob('S*/*.md'):
    for m in re.findall(r'friend/[a-z]+ @ ([0-9a-f]+)', open(f).read()):
        fileshas.add(m)
missing=allshas-fileshas
print("total commits:", len(allshas), "transcribed:", len(fileshas), "missing:", len(missing))
for m in missing: print(m, sha_branch.get(m))
PY
